// Lea FR — Recrutement artisans partenaires MaRenoFacile (B2B, fr)
// Clips: bucket/lea_*.mp3. Contrat I/O identique a renofacile 03.
function norm(t) {
  return (t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

// Bucket DEDIE Lea FR — ne PAS lire $env.STORAGE_BUCKET_URL (partage/pollue par Sofia).
const bucket = ($env.LEA_FR_STORAGE_BUCKET_URL || 'https://intellixcrm.com/lea-fr-tts').replace(/\/$/, '');
const audioFile = (name) => `${bucket}/${name}.mp3`;

function pickReaskClip(etape) {
  const map = {
    GREETING: 'lea_ouverture',
    PITCH: 'lea_pitch',
    Q_METIER: 'lea_q_metier',
    Q_TERRITOIRE: 'lea_q_territoire',
    CLOSING_RDV: 'lea_valeur_closing',
    CONFIRM_RDV: 'lea_confirm',
  };
  return audioFile(map[etape] || 'lea_fallback');
}

// Objections communes -> clip + on repart en attente de dispo (CLOSING_RDV)
function detectObjection(t) {
  if (/\b(pas le temps|pas maintenant|occupe|rappelez|rappeler plus tard|plus tard|pas dispo|pas disponible)\b/.test(t)) return 'pas_temps';
  if (/\b(deja des leads|j en ai deja|deja fournisseur|deja une plateforme|deja des clients|assez de travail|carnet plein|complet|pas besoin)\b/.test(t)) return 'deja_leads';
  if (/\b(combien|prix|tarif|ca coute|cout|c est payant|gratuit)\b/.test(t)) return 'prix';
  if (/\b(connais pas|jamais entendu|c est qui|qui etes vous|demarchage|c est quoi|vous etes qui|confiance|arnaque)\b/.test(t)) return 'connais_pas';
  if (/\b(envoyez|envoie|mail|email|courriel|documentation|par ecrit|brochure|plaquette)\b/.test(t)) return 'email';
  if (/\b(secteur|zone|territoire.*pris|deja pris|disponible.*secteur)\b/.test(t)) return 'secteur';
  if (/\b(engagement|abonnement|contrat|duree|s engager|long terme)\b/.test(t)) return 'engagement';
  return null;
}

const OBJ_CLIP = {
  pas_temps: 'lea_obj_pas_temps',
  deja_leads: 'lea_obj_deja_leads',
  prix: 'lea_obj_prix',
  connais_pas: 'lea_obj_connais_pas',
  email: 'lea_obj_email',
  secteur: 'lea_obj_secteur',
  engagement: 'lea_obj_engagement',
};

function detectDispo(t) {
  if (/\b(matin|matinee|avant midi|tot|debut de journee)\b/.test(t)) return 'matin';
  if (/\b(fin de journee|apres midi|apres-midi|soir|fin d apres|tard)\b/.test(t)) return 'fin de journee';
  if (/\b(lundi|mardi|mercredi|jeudi|vendredi|demain|cette semaine|semaine prochaine)\b/.test(t)) return t.slice(0, 40);
  if (/\d{1,2}\s*h/.test(t)) return t.slice(0, 40);
  if (/\b(quand vous voulez|peu importe|comme vous voulez|n importe|disponible|libre|ca me va|d accord|ok)\b/.test(t)) return 'flexible';
  return null;
}

function classify(etape, transcript) {
  const t = norm(transcript);
  if (!t) return { intent: 'silence' };
  if (/\b(ne plus appeler|retirez|retirer mon numero|liste noire|do not call|arretez de|supprimez)\b/.test(t)) return { intent: 'dnc' };
  const oui = /\b(oui|ouais|ok|d accord|dac|bien sur|volontiers|allez y|je vous ecoute|pourquoi pas|carrement)\b/.test(t);
  const non = /^(non|nan|nope)\b/.test(t) || /\b(pas interesse|non merci|ca m interesse pas|laissez moi|au revoir|pas envie)\b/.test(t);

  // Répondeur / messagerie : ne jamais avancer le script
  if (/\b(repondeur|messagerie|laissez|veuillez laisser|apres le bip|bip sonore|boite vocale|pas disponible|joindre|raccrocher|enregistrem|coordonnees|tapez|composez|signal sonore)\b/.test(t)) {
    return { intent: 'messagerie' };
  }
  if (etape === 'GREETING') {
    if (/\b(allo|bonjour|oui allo|j ecoute|oui c est moi|lui meme|elle meme)\b/.test(t)) return { intent: 'oui' };
    const obj = detectObjection(t);
    if (obj === 'pas_temps') return { intent: 'pas_temps' };
    if (non && !oui) return { intent: 'non' };
    if (oui) return { intent: 'oui' };
    if (obj) return { intent: 'objection', valeur: obj };
    // Ne plus traiter un fragment STT (Votre/Ce/Nous/16.) comme un oui
    if (t.length >= 12 && /\b(oui|ouais|ok|d accord|je vous ecoute|pourquoi pas)\b/.test(t)) return { intent: 'oui' };
  }

  // Etapes de qualification / closing : objection d'abord, sinon capture reponse
  const obj = detectObjection(t);
  if (etape === 'CLOSING_RDV' || etape === 'CONFIRM_RDV') {
    const dispo = detectDispo(t);
    if (etape === 'CONFIRM_RDV' && (oui || /\b(c est ca|exact|parfait|confirme|correct)\b/.test(t)) && !non) return { intent: 'confirme' };
    if (dispo) return { intent: 'dispo', valeur: dispo };
    if (obj) return { intent: 'objection', valeur: obj };
    if (non) return { intent: 'non' };
    if (oui) return { intent: 'dispo', valeur: 'flexible' };
    return { intent: 'incertain' };
  }
  if (obj) return { intent: 'objection', valeur: obj };
  if (non) return { intent: 'non' };
  // PITCH / Q_METIER / Q_TERRITOIRE : toute reponse audible = capture
  if (t.length >= 2) return { intent: 'ok', valeur: transcript.slice(0, 80) };
  return { intent: 'incertain' };
}

function buildCrmPayload(session, ev, opts) {
  const phone = session?.data?.telephone || session?.telephone || ev.to || ev.from || '';
  if (!phone || !session) return null;
  const d = session.data || {};
  const qualified = !!(opts && opts.qualified);
  return {
    call_sid: ev.call_sid || '',
    partner_id: ev.partner_id || ev.lead_id || '',
    lead_id: ev.lead_id || ev.partner_id || '',
    telephone: phone,
    statut: (opts && opts.statut) || session.statut || 'non_fait',
    etat_final: (opts && opts.statut) || session.statut || 'non_fait',
    metier: d.metier || '',
    territoire: d.territoire || '',
    generation_actuelle: d.generation || '',
    dispo_rdv: d.dispo_rdv || '',
    rdv_pris: qualified,
    qualification_complete: qualified,
    transcript: (session.transcript_log || []).join('\n'),
    recording_url: ev.recording_url || '',
    duration_sec: session.duree_sec || ev.duration_sec || 0,
    campaign: ev.campaign || $env.VICIDIAL_CAMPAIGN || 'DW_LEAFR',
    agent_id: ev.agent_id || $env.AGENT_ID || 'lea-fr',
  };
}

const _raw = $input.first().json;
const ev = (_raw && _raw.body && typeof _raw.body === 'object') ? _raw.body : _raw;

if (ev.event_type === 'amd_result' && ['machine', 'fax', 'not_sure'].includes((ev.amd_result || '').toLowerCase())) {
  return [{ json: {
    action: 'hangup', call_sid: ev.call_sid, qualified: false, statut: 'messagerie',
    audio_url: audioFile('lea_exit_timeout'),
    crm_payload: { telephone: ev.to || ev.from || '', statut: 'messagerie', etat_final: 'messagerie',
      campaign: ev.campaign || 'DW_LEAFR', agent_id: ev.agent_id || 'lea-fr' },
    event: ev,
  } }];
}

if (ev.event_type === 'call_ended' || ev.action === 'hangup') {
  const sd = $getWorkflowStaticData('global');
  const session = (sd.lea_fr_sessions || {})[ev.call_sid];
  const crm_payload = session ? buildCrmPayload(session, ev, { qualified: session.qualified, statut: session.statut }) : null;
  return [{ json: { action: 'hangup', call_sid: ev.call_sid, crm_payload, session, event: ev } }];
}

const callSid = ev.call_sid || '';
const sd = $getWorkflowStaticData('global');
if (!sd.lea_fr_sessions) sd.lea_fr_sessions = {};
let session = sd.lea_fr_sessions[callSid];
if (!session) {
  session = {
    etape: 'GREETING',
    telephone: ev.to || ev.from || '',
    duree_sec: 0,
    silence_count: 0,
    obj_count: 0,
    soft_limit: parseInt($env.AGENT_MAX_SEC || '170', 10),
    qualified: false,
    statut: 'en_cours',
    data: { telephone: ev.to || ev.from || '', metier: null, territoire: null, generation: null, dispo_rdv: null },
    transcript_log: [],
  };
  sd.lea_fr_sessions[callSid] = session;
}
if (session.silence_count == null) session.silence_count = 0;
if (session.obj_count == null) session.obj_count = 0;

if (ev.event_type !== 'recording_ready' || (!ev.recording_url && !ev.recording_b64 && !ev.transcript)) {
  if (session.etape === 'GREETING') {
    return [{ json: { action: 'play_audio', call_sid: callSid, qualified: false, statut: 'en_cours',
      audio_url: pickReaskClip('GREETING'), session, event: ev } }];
  }
  return [{ json: { action: 'hangup', error: 'no_recording', event: ev } }];
}

let transcript = (ev.transcript || '').trim();
if (!transcript && (ev.recording_url || ev.recording_b64)) {
  const odooBase = ($env.ODOO_URL || 'http://127.0.0.1:8069').replace(/\/$/, '');
  const sttKey = ($env.SOFIA_STT_WEBHOOK_KEY || 'doorway-sofia-stt').trim();
  try {
    const sttRes = await this.helpers.httpRequest({
      method: 'POST', url: odooBase + '/api/renov/stt/deepgram',
      headers: { 'Content-Type': 'application/json', 'X-Renov-Stt-Key': sttKey },
      body: { recording_url: ev.recording_url || '', recording_b64: ev.recording_b64 || '', language: 'fr' },
      json: true, timeout: 25000,
    });
    transcript = (sttRes && sttRes.transcript) || '';
  } catch (e) { transcript = ''; }
}

const etape = session.etape;
const cls = classify(etape, transcript);
session.transcript_log.push(`[${etape}] ${transcript || '(silence)'} -> ${cls.intent}${cls.valeur ? '/' + cls.valeur : ''}`);
session.duree_sec += Math.max(4, parseInt(ev.duration_sec, 10) || 6);

let route = { hangup: false, qualified: false, statut: 'en_cours', audio_url: '' };

function goObjection(objKey) {
  session.obj_count += 1;
  if (session.obj_count > 2) {
    return { hangup: true, qualified: false, statut: 'pas_interesse', audio_url: audioFile('lea_exit_refus') };
  }
  if (objKey === 'pas_temps') {
    // capture rappel puis raccroche
    session.etape = 'CLOSING_RDV';
    return { hangup: false, audio_url: audioFile('lea_obj_pas_temps') };
  }
  session.etape = 'CLOSING_RDV'; // toutes les objections finissent par proposer un creneau
  return { hangup: false, audio_url: audioFile(OBJ_CLIP[objKey] || 'lea_fallback') };
}

if (session.duree_sec >= session.soft_limit) {
  route = { hangup: true, qualified: false, statut: 'non_fait', audio_url: audioFile('lea_exit_timeout') };
} else if (cls.intent === 'dnc') {
  route = { hangup: true, qualified: false, statut: 'dnc', audio_url: audioFile('lea_exit_dnc') };
} else if (cls.intent === 'objection') {
  route = goObjection(cls.valeur);
} else if (cls.intent === 'silence') {
  session.silence_count += 1;
  const lim = etape === 'GREETING' ? 3 : 3;
  if (session.silence_count >= lim) {
    route = { hangup: true, qualified: false, statut: 'non_fait', audio_url: audioFile('lea_exit_timeout') };
  } else {
    route = { hangup: false, audio_url: (etape === 'GREETING' ? audioFile('lea_fallback') : pickReaskClip(etape)) };
  }
} else {
  session.silence_count = 0;
  if (etape === 'GREETING') {
    if (cls.intent === 'messagerie') { route = { hangup: true, qualified: false, statut: 'messagerie', audio_url: audioFile('lea_exit_timeout') }; }
    else if (cls.intent === 'oui') { session.etape = 'PITCH'; route = { hangup: false, audio_url: audioFile('lea_pitch') }; }
    else if (cls.intent === 'pas_temps') { route = goObjection('pas_temps'); }
    else if (cls.intent === 'non') { route = { hangup: true, qualified: false, statut: 'pas_interesse', audio_url: audioFile('lea_exit_refus') }; }
    else { route = { hangup: false, audio_url: pickReaskClip('GREETING') }; }
  } else if (etape === 'PITCH') {
    if (cls.intent === 'ok') { session.data.generation = cls.valeur; session.etape = 'Q_METIER'; route = { hangup: false, audio_url: audioFile('lea_q_metier') }; }
    else if (cls.intent === 'non') { route = goObjection('deja_leads'); }
    else { route = { hangup: false, audio_url: pickReaskClip('PITCH') }; }
  } else if (etape === 'Q_METIER') {
    if (cls.intent === 'ok') { session.data.metier = cls.valeur; session.etape = 'Q_TERRITOIRE'; route = { hangup: false, audio_url: audioFile('lea_q_territoire') }; }
    else { route = { hangup: false, audio_url: pickReaskClip('Q_METIER') }; }
  } else if (etape === 'Q_TERRITOIRE') {
    if (cls.intent === 'ok') { session.data.territoire = cls.valeur; session.etape = 'CLOSING_RDV'; route = { hangup: false, audio_url: audioFile('lea_valeur_closing') }; }
    else { route = { hangup: false, audio_url: pickReaskClip('Q_TERRITOIRE') }; }
  } else if (etape === 'CLOSING_RDV') {
    if (cls.intent === 'dispo') { session.data.dispo_rdv = cls.valeur; session.etape = 'CONFIRM_RDV'; route = { hangup: false, audio_url: audioFile('lea_confirm') }; }
    else if (cls.intent === 'non') { route = { hangup: true, qualified: false, statut: 'pas_interesse', audio_url: audioFile('lea_exit_refus') }; }
    else { route = { hangup: false, audio_url: pickReaskClip('CLOSING_RDV') }; }
  } else if (etape === 'CONFIRM_RDV') {
    if (cls.intent === 'confirme' || cls.intent === 'dispo') {
      session.etape = 'closing';
      route = { hangup: true, qualified: true, statut: 'rdv_pris', audio_url: audioFile('lea_closing') };
    } else if (cls.intent === 'non') {
      session.etape = 'CLOSING_RDV'; route = { hangup: false, audio_url: audioFile('lea_valeur_closing') };
    } else { route = { hangup: false, audio_url: pickReaskClip('CONFIRM_RDV') }; }
  }
}

session.qualified = route.qualified;
session.statut = route.statut;
sd.lea_fr_sessions[callSid] = session;

const crm_payload = route.hangup ? buildCrmPayload(session, ev, { qualified: route.qualified, statut: route.statut }) : null;

return [{ json: {
  action: route.hangup ? 'hangup' : 'play_audio',
  call_sid: callSid, qualified: route.qualified, statut: route.statut,
  audio_url: route.audio_url, crm_payload, session, transcript, event: ev,
} }];
